import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"js节流函数","description":"节流： 节流函数允许一个函数在规定的时间内只执行一次。 自己理解：高频事件触发时，会不断调用函数，但调用的频率由我们控制。 两者区别： 防抖只有高频事件停止后才会调用函数； 节流在高频事件触发的过程中会不断调用函数，但在规定时间内只会执行一次。 比如在页面的无限加载场景下，我们需。","frontmatter":{"title":"js节流函数","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","面试与手写"],"description":"节流： 节流函数允许一个函数在规定的时间内只执行一次。 自己理解：高频事件触发时，会不断调用函数，但调用的频率由我们控制。 两者区别： 防抖只有高频事件停止后才会调用函数； 节流在高频事件触发的过程中会不断调用函数，但在规定时间内只会执行一次。 比如在页面的无限加载场景下，我们需。","sidebarWeight":16,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面试/手写/js节流函数.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/09-面试与手写/手写/js节流函数.md","filePath":"posts/JavaScript系统教程/09-面试与手写/手写/js节流函数.md"}'),n={name:"posts/JavaScript系统教程/09-面试与手写/手写/js节流函数.md"};function i(s,e,c,l,d,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="js节流函数" tabindex="-1">js节流函数 <a class="header-anchor" href="#js节流函数" aria-label="Permalink to &quot;js节流函数&quot;">​</a></h1><blockquote><p>本节目标：理解“js节流函数”的核心思路，并能把它用于实际开发或面试表达。 <strong>节流：</strong> 节流函数允许一个函数在规定的时间内只执行一次。 自己理解：高频事件触发时，会不断调用函数，但调用的频率由我们控制。 两者区别：</p></blockquote><ul><li>防抖只有高频事件停止后才会调用函数；</li><li>节流在高频事件触发的过程中会不断调用函数，但在规定时间内只会执行一次。</li></ul><p>比如在页面的无限加载场景下，我们需要用户在滚动页面时，<strong>每隔一段时间发一次</strong> <code>Ajax</code> <strong>请求，而不是在用户停下滚动页面操作时才去请求数据</strong>。 主要有两种实现方法：</p><ul><li>时间戳</li><li>定时器</li></ul><p><strong>时间戳实现</strong>： var throttle = function (func, delay) { var prev = Date.now(); return function () { var context = this; var args = arguments; var now = Date.now(); if (now - prev &gt;= delay) { func.apply(context, args); prev = Date.now(); } } }</p><p><strong>定时器实现：</strong> 当触发事件的时候，我们设置一个定时器，再触发事件的时候，如果定时器存在，就不执行；直到<code>delay</code>秒后，定时器执行执行函数，清空定时器，这样就可以设置下个定时器。 var throttle = function (func, delay) { var timer = null; return funtion(){ var context = this; var args = arguments; if (!timer) { timer = setTimeout(function () { func.apply(context, args); timer = null; }, delay); } } }</p><ul><li>当第一次触发事件时，肯定不会立即执行函数，而是在<code>delay</code>秒后才执行。</li><li>之后<a href="https://www.baidu.com/s?wd=%E8%BF%9E%E7%BB%AD%E4%B8%8D%E6%96%AD&amp;tn=24004469_oem_dg&amp;rsv_dl=gh_pl_sl_csd" target="_blank" rel="noreferrer">连续不断</a>触发事件，也会每<code>delay</code>秒执行一次。</li><li>当最后一次停止触发后，由于定时器的<code>delay</code>延迟，可能还会执行一次函数。</li></ul><p>可以综合使用时间戳与定时器，完成一个事件触发时立即执行，触发完毕还能执行一次的节流函数： var throttle = function (func, delay) { var timer = null; var startTime = Date.now(); return function () { var curTime = Date.now(); var remaining = delay - (curTime - startTime); var context = this; var args = arguments; clearTimeout(timer); if (remaining &lt;= 0) { func.apply(context, args); startTime = Date.now(); } else { timer = setTimeout(func, remaining); } } } 需要在每个<code>delay</code>时间中一定会执行一次函数，因此在节流函数内部使用开始时间、当前时间与<code>delay</code>来计算<code>remaining</code>，当<code>remaining\\&lt;=0</code>时表示该执行函数了，如果还没到时间的话就设定在<code>remaining</code>时间后再触发。当然在<code>remaining</code>这段时间中如果又一次发生事件，那么会取消当前的计时器，并重新计算一个<code>remaining</code>来判断当前状态。</p></div>',1)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
